INSERT INTO `experiencia` VALUES ('cmn7079i70001wt093ivl2943','Taller de Arena Cinética','Regulación Sensorial','Un espacio de exploración independiente donde los niños moldean, aplastan y crean con arena cinética interactiva.','Una experiencia inmersiva en un entorno tecnológicamente diseñado donde los niños interactúan libremente con arena cinética especial. El ambiente responde a sus movimientos, creando una estimulación autónoma del sistema propioceptivo y táctil.',45,60,'3 - 8 años','Máx. 4 niños','[\"Regulación táctil\", \"Motricidad fina\", \"Creatividad\", \"Concentración\"]','[\"Materiales sensoriales interactivos\", \"Entorno dinámico adaptativo\", \"Informe de actividad\", \"Snack saludable\"]','#e8d5c4','https://cdn.abacus.ai/images/222e92e6-4607-45ea-bda0-8bd303f890ce.png',4.9,124,'2026-03-26 11:00:05.983','2026-03-26 18:30:25.198'),('cmn7079in0037wt096agh5x5h','Circuito de Psicomotricidad','Conciencia Corporal','Circuito interactivo de movimiento con rampas, túneles y estaciones que responden al niño.','Un circuito dinámico diseñado con herramientas interactivas: rampas de espuma, túneles sensoriales y estaciones de equilibrio que se adaptan al ritmo de cada niño.',52,75,'3 - 12 años','Máx. 6 niños','[\"Equilibrio\", \"Coordinación\", \"Fuerza muscular\", \"Planificación motora\"]','[\"Circuito interactivo completo\", \"Sensores de movimiento\", \"Evaluación motora digital\", \"Plan de ejercicios personalizado\"]','#d5c8b8','https://cdn.abacus.ai/images/09ee6f32-4113-4a93-b195-640541be4f1f.png',4.9,156,'2026-03-26 11:00:06.000','2026-03-26 18:30:25.205'),('cmn7079iu004swt094kh27nk0','Sesión de Arte Sensorial','Regulación Emocional','Estación de arte interactiva con pinturas sensoriales y materiales táctiles para la expresión libre.','Un espacio de exploración artística donde las herramientas dinámicas invitan al niño a interactuar con pinturas sensoriales, texturas variadas y arcilla. El entorno está diseñado para la interacción libre y autónoma.',42,60,'2 - 9 años','Máx. 5 niños','[\"Expresión emocional\", \"Tolerancia táctil\", \"Creatividad\", \"Autoestima\"]','[\"Materiales interactivos completos\", \"Entorno de arte adaptativo\", \"Obra para llevar\", \"Reporte de actividad\"]','#ddd0c0','https://cdn.abacus.ai/images/eb37817d-8247-42f3-a0b5-4e2a20da06c5.png',4.7,89,'2026-03-26 11:00:06.007','2026-03-26 18:30:25.208'),('cmn7079j2006dwt09dj3qobql','Exploración Táctil Guiada','Regulación Sensorial','Sesión guiada de exploración de diferentes texturas y materiales para desarrollar tolerancia táctil.','Los niños exploran superficies suaves, rugosas, frías y cálidas en un ambiente seguro y controlado.',40,50,'2 - 7 años','Máx. 4 niños','[\"Tolerancia táctil\", \"Curiosidad\", \"Regulación\", \"Concentración\"]','[\"Kit de texturas\", \"Terapeuta especializado\", \"Informe de progreso\"]','#e5dcd0','https://cdn.abacus.ai/images/8e7ed4e0-0659-47a6-a10f-cdefbf0ca061.png',4.8,76,'2026-03-26 11:00:06.014','2026-03-26 11:00:06.014'),('cmn7079j9007ywt09w539evm5','Terapia Vestibular en Columpio','Conciencia Corporal','Actividades en columpio terapéutico para estimular el sistema vestibular y el equilibrio.','Sesión en columpios sensoriales especiales que proporcionan estimulación vestibular controlada y segura.',48,45,'3 - 10 años','Máx. 3 niños','[\"Equilibrio\", \"Calma\", \"Regulación vestibular\", \"Coordinación\"]','[\"Columpio sensorial\", \"Terapeuta certificado\", \"Evaluación vestibular\"]','#d8e0d5','https://cdn.abacus.ai/images/fc43602f-08e2-4cdb-83c4-7b985cb85c90.png',4.9,112,'2026-03-26 11:00:06.022','2026-03-26 11:00:06.022'),('cmn7gadoa0005wfsueaurx940','Exploración Táctil Interactiva','Regulación Sensorial','Entorno inteligente con diferentes texturas y materiales que responden al tacto para una estimulación autónoma.','Los niños exploran superficies suaves, rugosas, frías y cálidas en un entorno interactivo que adapta la experiencia a cada niño de forma autónoma.',40,50,'2 - 7 años','Máx. 4 niños','[\"Tolerancia táctil\", \"Curiosidad\", \"Regulación\", \"Concentración\"]','[\"Kit de texturas inteligente\", \"Entorno adaptativo\", \"Reporte de interacción\"]','#e5dcd0','https://cdn.abacus.ai/images/8e7ed4e0-0659-47a6-a10f-cdefbf0ca061.png',4.8,76,'2026-03-26 18:30:25.211','2026-03-26 18:30:25.211'),('cmn7gadoj001qwfsuf0gc4la2','Columpio Vestibular Interactivo 2','Conciencia Corporal','Columpios sensoriales inteligentes que proporcionan estimulación vestibular personalizada y segura.','El entorno de columpios sensoriales se adapta automáticamente al niño, proporcionando estimulación vestibular controlada en un ambiente diseñado para la interacción libre.',48,45,'3 - 10 años','Máx. 3 niños','[\"Equilibrio\", \"Calma\", \"Regulación vestibular\", \"Coordinación\"]','[\"Columpio sensorial inteligente\", \"Sensores de movimiento\", \"Evaluación vestibular digital\"]','#4ca62b','https://cdn.abacus.ai/images/fc43602f-08e2-4cdb-83c4-7b985cb85c90.png',4.9,112,'2026-03-26 18:30:25.220','2026-04-24 05:39:16.000');
